    auto out_sizes = std::vector<int64_t>{x.size(0), weight.size(0)};
    at::Tensor result = at::empty(out_sizes, x.options());
    EXEC_NPU_CMD(aclnnMatmulGeluSoftmaxCustom, x, weight, bias, result);
    return result;
}

